import{_ as e,o,c as n,ag as a}from"./chunks/framework.qXLDknWC.js";const c=JSON.parse('{"title":"AI Setup","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/ai-setup.md","filePath":"configuration/ai-setup.md"}'),s={name:"configuration/ai-setup.md"};function r(i,t,l,d,p,h){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="ai-setup" tabindex="-1">AI Setup <a class="header-anchor" href="#ai-setup" aria-label="Permalink to &quot;AI Setup&quot;">​</a></h1><p>Character Vault&#39;s AI features — the Orion assistant and AI toolbar — require an AI provider endpoint. This guide covers every option in the settings panel.</p><h2 id="opening-settings" tabindex="-1">Opening Settings <a class="header-anchor" href="#opening-settings" aria-label="Permalink to &quot;Opening Settings&quot;">​</a></h2><ol><li>Open a character in the workspace.</li><li>Click <strong>Settings</strong> in the workspace header.</li><li>The settings modal opens with five tabs: <strong>AI Config</strong>, <strong>Sampler</strong>, <strong>Prompts</strong>, <strong>Studio</strong>, and <strong>Sections</strong>.</li><li>Click <strong>Save Settings</strong> at the bottom when you&#39;re done. Changes don&#39;t take effect until you save.</li></ol><p>You can close the panel with <strong>Cancel</strong> or <code>Escape</code> to discard changes.</p><h2 id="ai-config-tab" tabindex="-1">AI Config Tab <a class="header-anchor" href="#ai-config-tab" aria-label="Permalink to &quot;AI Config Tab&quot;">​</a></h2><h3 id="security-notice" tabindex="-1">Security Notice <a class="header-anchor" href="#security-notice" aria-label="Permalink to &quot;Security Notice&quot;">​</a></h3><p>At the top of the AI Config tab, a security banner reminds you that your API key is stored locally in your browser. Click <strong>Clear AI Settings</strong> to remove all AI configuration (key, URL, model) — your characters are not affected. A confirmation step prevents accidental clears. Prompt templates and <strong>per-prompt model mappings</strong> on the Prompts tab are kept (they do not store secrets).</p><h3 id="api-base-url" tabindex="-1">API Base URL <a class="header-anchor" href="#api-base-url" aria-label="Permalink to &quot;API Base URL&quot;">​</a></h3><p>Choose a provider preset from the dropdown, or select <strong>Custom URL</strong> to type in any OpenAI-compatible endpoint:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Preset</th><th style="text-align:left;">Base URL</th><th style="text-align:left;">When to Use</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Nano-GPT</strong></td><td style="text-align:left;"><code>https://nano-gpt.com/api/v1</code></td><td style="text-align:left;">NanoGPT hosted endpoint. Supports provider selection and subscription billing.</td></tr><tr><td style="text-align:left;"><strong>OpenRouter</strong></td><td style="text-align:left;"><code>https://openrouter.ai/api/v1</code></td><td style="text-align:left;">OpenRouter multi-model gateway.</td></tr><tr><td style="text-align:left;"><strong>Minimax</strong></td><td style="text-align:left;"><code>https://api.minimax.io/v1</code></td><td style="text-align:left;">OpenAI-compatible endpoint. API keys start with <code>sk-cp</code>.</td></tr><tr><td style="text-align:left;"><strong>LM Studio / localhost</strong></td><td style="text-align:left;"><code>http://127.0.0.1:1234/v1</code></td><td style="text-align:left;">Local inference with LM Studio.</td></tr><tr><td style="text-align:left;"><strong>Custom URL</strong></td><td style="text-align:left;">Any URL</td><td style="text-align:left;">Any OpenAI-compatible endpoint (e.g., a self-hosted API).</td></tr></tbody></table><p>When you switch presets, the text field below updates. Your API key and model selection are <strong>remembered per base URL</strong> — switching back to a previous provider restores your saved key and model.</p><p>The helper text below the URL field changes based on the selected preset. For custom URLs, it reads: &quot;Pick a preset above or enter a custom OpenAI-compatible endpoint.&quot;</p><h3 id="api-key" tabindex="-1">API Key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API Key&quot;">​</a></h3><p>Enter your API key in the password field. The key is saved per base URL — if you switch providers and come back, your key is restored.</p><p>Some presets include a link to the provider&#39;s key management page — click <strong>Get your key ↗</strong> next to the API Key label.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Your API key is stored locally in your browser&#39;s storage. It could be accessed by malicious browser extensions or if someone gains physical access to your unlocked computer.</p></div><h3 id="sign-in-with-nanogpt-pkce" tabindex="-1">Sign in with NanoGPT (PKCE) <a class="header-anchor" href="#sign-in-with-nanogpt-pkce" aria-label="Permalink to &quot;Sign in with NanoGPT (PKCE)&quot;">​</a></h3><p>When the <strong>Nano-GPT</strong> preset is selected, a <strong>Sign in with NanoGPT</strong> button appears next to the API Key field. Instead of pasting an API key, you can sign in with your NanoGPT account — CharacterVault walks you through a secure OAuth flow using PKCE (Proof Key for Code Exchange), no client secret stored anywhere, no password ever seen by this app.</p><p><strong>How it works</strong></p><ol><li>Click <strong>Sign in with NanoGPT</strong>. A new browser window/tab opens to NanoGPT&#39;s authorization page.</li><li>Approve the request on NanoGPT&#39;s site.</li><li>NanoGPT redirects back to a small relay page that returns the authorization code to CharacterVault.</li><li>CharacterVault exchanges the code (plus the one-time PKCE verifier) for an API key and drops it into the API Key field for you.</li><li>Your available models are <strong>automatically fetched</strong> — the model dropdown is populated as soon as sign-in completes, so you can pick a model and start chatting immediately.</li></ol><p>The success toast confirms the result, e.g. <strong>&quot;Signed in. Fetched 47 models.&quot;</strong></p><div class="warning custom-block"><p class="custom-block-title">Browser popups must be allowed</p><p>The sign-in flow opens a new window or tab. If your browser blocks popups for this site, the button will appear to do nothing. Allow popups for <code>spaceman2408.github.io</code> (or your hosted origin) and try again. If you previously dismissed the permission, click the popup-blocker icon in the address bar to allow them for this site.</p></div><div class="warning custom-block"><p class="custom-block-title">Mobile browser support</p><p>PKCE sign-in works best on desktop browsers. Mobile support depends on the browser:</p><ul><li><strong>Chrome on Android</strong> — Works. The sign-in opens in a new tab and returns successfully.</li><li><strong>Other mobile browsers</strong> — May work, may not. Some mobile browsers handle popup/tab handoff differently and can fail to relay the authorization code back to the app. If sign-in doesn&#39;t complete on your phone, paste an API key manually instead.</li></ul><p>If you&#39;re on mobile and the button doesn&#39;t progress past &quot;Signing in...&quot;, open the page in Chrome or paste your API key directly into the API Key field.</p></div><p>You can still paste an API key manually at any time — the two flows are interchangeable.</p><h3 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h3><p>Click the model field (or <strong>Fetch models</strong>) to load and choose a model. Selection opens a <strong>sheet</strong> (bottom sheet on phones, centered dialog on larger screens) so the list is not clipped by the settings panel:</p><ul><li><strong>Search</strong> — Type in the filter field to narrow models by name or ID. On mobile, the search field uses a large enough font to avoid iOS zoom.</li><li><strong>Keyboard</strong> — Press <code>Enter</code> to select the first match, <code>Escape</code> to close the sheet only (not the whole Settings panel).</li><li><strong>Tap outside / Close</strong> — Dismiss without changing the selection.</li></ul><p>Model selections are saved per base URL, so switching providers remembers your last chosen model for each.</p><p>This is your <strong>global default</strong> model — used by Orion chat, AI Creation Studio, and any toolbar prompt that is still set to <strong>Default</strong> on the <a href="#prompts-tab">Prompts tab</a>.</p><h3 id="provider-nanogpt-only" tabindex="-1">Provider (NanoGPT Only) <a class="header-anchor" href="#provider-nanogpt-only" aria-label="Permalink to &quot;Provider (NanoGPT Only)&quot;">​</a></h3><p>Some NanoGPT models support <strong>provider selection</strong> — choosing which backend serves the request. When available, a <strong>Provider</strong> control appears below the model selector. It uses the same sheet pattern as the model picker. Each provider shows its per-1k-token pricing for input and output.</p><ul><li><strong>Platform default</strong> — Let NanoGPT auto-select the best provider.</li><li><strong>Specific provider</strong> — Pick a named provider to control cost or latency.</li></ul><p>Provider preferences are saved per model — switching models remembers your choice.</p><h3 id="nanogpt-account-overview" tabindex="-1">NanoGPT Account overview <a class="header-anchor" href="#nanogpt-account-overview" aria-label="Permalink to &quot;NanoGPT Account overview&quot;">​</a></h3><p>When the Nano-GPT preset is selected, a <strong>NanoGPT Account</strong> card shows:</p><ul><li><strong>Balance</strong> (USD / Nano) from NanoGPT’s check-balance API</li><li><strong>Subscription status</strong> (active / grace / not active) and weekly input-token quota when available</li></ul><p>Refresh is rate-limited (about 30 seconds). Closing and reopening Settings within about a minute reuses the last result so the APIs are not hit again.</p><p><strong>Subscription status and weekly tokens:</strong> On the <strong>official hosted app</strong> and on <strong>localhost</strong> (<code>npm run dev</code>), this works with no extra setup. You only need a small proxy if you <strong>self-host a production build</strong> of CharacterVault. Full walkthrough: <a href="/CharacterVault/docs/configuration/nanogpt-usage-proxy">NanoGPT Usage Proxy (Self-Hosted Production)</a>.</p><h3 id="nanogpt-options" tabindex="-1">NanoGPT Options <a class="header-anchor" href="#nanogpt-options" aria-label="Permalink to &quot;NanoGPT Options&quot;">​</a></h3><p>When the NanoGPT preset is selected, two additional toggles appear:</p><ul><li><strong>Subscription models only</strong> — When on, clicking <strong>Fetch</strong> only returns models included in your NanoGPT subscription. When off, paid models are also listed.</li><li><strong>Pay-as-you-go billing</strong> — Force pay-as-you-go pricing even with an active subscription. This is required for provider selection on subscription-covered models.</li></ul><h3 id="advanced-options" tabindex="-1">Advanced Options <a class="header-anchor" href="#advanced-options" aria-label="Permalink to &quot;Advanced Options&quot;">​</a></h3><p>Three toggle switches control streaming and reasoning:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Default</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enable streaming</strong></td><td style="text-align:left;">Off</td><td style="text-align:left;">AI responses appear in real-time as they&#39;re generated. When off, the full response appears at once after completion.</td></tr><tr><td style="text-align:left;"><strong>Enable reasoning</strong></td><td style="text-align:left;">Off</td><td style="text-align:left;">Enables thinking/reasoning mode for models that support it (DeepSeek, Qwen/QwQ, OpenAI o1/o3/o4-mini, OpenRouter reasoning models).</td></tr><tr><td style="text-align:left;"><strong>Show reasoning</strong></td><td style="text-align:left;">On</td><td style="text-align:left;">When reasoning is enabled, the AI&#39;s thinking process is shown in a collapsible section before the response.</td></tr></tbody></table><p>When reasoning is enabled, a <strong>Reasoning Effort</strong> dropdown appears (Minimal through Max / Extra high). Which levels a model accepts depends on the provider: GPT-style models often use Minimal–High (and Extra high), while many SOTA thinking models (DeepSeek V4, GLM-5.x, Kimi, etc.) mainly use High and Max.</p><p>Full guide: <a href="/CharacterVault/docs/configuration/reasoning-effort">Reasoning Effort</a>.</p><h2 id="sampler-tab" tabindex="-1">Sampler Tab <a class="header-anchor" href="#sampler-tab" aria-label="Permalink to &quot;Sampler Tab&quot;">​</a></h2><p>See <a href="/CharacterVault/docs/configuration/sampler-settings">Sampler Settings</a> for a full explanation of every parameter.</p><p>The Sampler tab includes:</p><ul><li><strong>Quick Presets</strong> — One-click <strong>Creative</strong>, <strong>Balanced</strong>, or <strong>Factual</strong> presets.</li><li><strong>Primary Samplers</strong> — Temperature, Top P, Min P, Top K sliders.</li><li><strong>Secondary Samplers</strong> — Repetition Penalty, Max Tokens sliders, and Context Length dropdown.</li></ul><h2 id="prompts-tab" tabindex="-1">Prompts Tab <a class="header-anchor" href="#prompts-tab" aria-label="Permalink to &quot;Prompts Tab&quot;">​</a></h2><p>The Prompts tab lets you edit the <strong>user prompt templates</strong> used by each AI toolbar operation, and optionally <strong>route each operation to a different endpoint and model</strong>.</p><p>Prompts are divided into two groups:</p><ul><li><strong>Primary Operations</strong> — Enhance, Rephrase, Custom. Each prompt is in a collapsible section. Click to expand and edit in a text area.</li><li><strong>Polish Operations</strong> — Shorten, Lengthen, Vivid, Emotion, Fix. Same collapsible layout.</li></ul><h3 id="prompt-text" tabindex="-1">Prompt text <a class="header-anchor" href="#prompt-text" aria-label="Permalink to &quot;Prompt text&quot;">​</a></h3><p>Every prompt must contain <code>${text}</code> — this is where your selected text gets inserted. The Custom (Instruct) prompt also requires <code>${instruction}</code> for your typed instruction. Validation errors appear inline if required placeholders are missing.</p><h3 id="per-prompt-model-routing" tabindex="-1">Per-prompt model routing <a class="header-anchor" href="#per-prompt-model-routing" aria-label="Permalink to &quot;Per-prompt model routing&quot;">​</a></h3><p>Under each expanded prompt, <strong>Model for this prompt</strong> controls which API endpoint and model run that operation:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">What it does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Endpoint</strong></td><td style="text-align:left;"><strong>Default (AI Config)</strong> uses your global base URL + model. Or pick Nano-GPT, OpenRouter, Minimax, LM Studio / localhost, or a custom URL you already configured.</td></tr><tr><td style="text-align:left;"><strong>Model</strong></td><td style="text-align:left;">When not on Default: open the same style of model sheet as AI Config, <strong>Fetch models</strong> for that endpoint, or type a model ID manually.</td></tr></tbody></table><p><strong>Examples</strong></p><ul><li>Map <strong>Fix</strong> to a fast NanoGPT model for cheap grammar passes.</li><li>Map <strong>Rephrase</strong> to OpenRouter’s DeepSeek (or another host) while Enhance stays on your global model.</li><li>Leave most ops on Default and only override the ones that need a specialist model.</li></ul><p><strong>Requirements</strong></p><ul><li>API keys are still managed on the <strong>AI Config</strong> tab (including per–base URL memory). The Prompts tab only <strong>selects</strong> among endpoints that already have a key (or local endpoints that do not need one).</li><li>A mapped prompt must have both an endpoint and a non-empty model ID, or Save is blocked.</li><li>Collapsed prompt headers show <code>→ {modelId}</code> when a mapping is set.</li></ul><p><strong>What is not routed (yet)</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">Surface</th><th style="text-align:left;">Uses</th></tr></thead><tbody><tr><td style="text-align:left;">AI toolbar ops (Enhance, Fix, …)</td><td style="text-align:left;">Per-prompt map, or global default</td></tr><tr><td style="text-align:left;">Lorebook <strong>AI key generation</strong> (✨)</td><td style="text-align:left;">The <strong>Custom / instruct</strong> mapping if set, otherwise global</td></tr><tr><td style="text-align:left;"><strong>Orion</strong> chat</td><td style="text-align:left;">Always global AI Config</td></tr><tr><td style="text-align:left;"><strong>AI Creation Studio</strong></td><td style="text-align:left;">Always global AI Config</td></tr></tbody></table><p>Sampler, streaming, and reasoning settings remain global (Sampler / AI Config tabs).</p><p><strong>Clear AI Settings</strong> removes keys and the global model, but keeps your prompt <strong>text</strong> and <strong>model mappings</strong> (you will need keys again before a mapped endpoint works).</p><p>For full details on placeholders and the toolbar, see <a href="/CharacterVault/docs/features/editor#customizing-ai-operation-prompts">Customizing AI Operation Prompts</a>.</p><h2 id="studio-tab" tabindex="-1">Studio Tab <a class="header-anchor" href="#studio-tab" aria-label="Permalink to &quot;Studio Tab&quot;">​</a></h2><p>The Studio tab controls UI preferences for the AI Creation Studio — primarily the <strong>I&#39;m Feeling Lucky</strong> vortex animation. Toggle it off if the visual effect gets distracting or slows down your device.</p><h2 id="sections-tab" tabindex="-1">Sections Tab <a class="header-anchor" href="#sections-tab" aria-label="Permalink to &quot;Sections Tab&quot;">​</a></h2><p>The Sections tab lets you customize the editor&#39;s section tab strip. Hide tabs you don&#39;t use, reorder the rest, and reset to defaults at any time. See <a href="/CharacterVault/docs/configuration/section-layout">Section Tab Layout</a> for the full guide.</p><h2 id="missing-v1-detection" tabindex="-1">Missing /v1 Detection <a class="header-anchor" href="#missing-v1-detection" aria-label="Permalink to &quot;Missing /v1 Detection&quot;">​</a></h2><p>If your API requests fail and the base URL doesn&#39;t end in <code>/v1</code>, the error message suggests adding <code>/v1</code> to the URL. This catches a common configuration mistake with OpenAI-compatible endpoints.</p><h2 id="context-length-max-tokens" tabindex="-1">Context Length &amp; Max Tokens <a class="header-anchor" href="#context-length-max-tokens" aria-label="Permalink to &quot;Context Length &amp; Max Tokens&quot;">​</a></h2><p>These are set on the <strong>Sampler</strong> tab:</p><ul><li><strong>Context Length</strong> — Dropdown from 2K to 1M tokens, plus a Custom option (4,096–1,000,000). This is the total window (input + output).</li><li><strong>Max Tokens</strong> — Slider from 100 to 8,192. The maximum tokens the AI will generate per response.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If Max Tokens is too close to Context Length, you&#39;ll see a warning. The AI needs room for both input and output. A 100-token safety margin is reserved automatically.</p></div><h2 id="troubleshooting-context-warnings" tabindex="-1">Troubleshooting Context Warnings <a class="header-anchor" href="#troubleshooting-context-warnings" aria-label="Permalink to &quot;Troubleshooting Context Warnings&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Warning</th><th style="text-align:left;">Cause</th><th style="text-align:left;">Fix</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>&quot;Selection is too long&quot;</strong></td><td style="text-align:left;">Selected text exceeds the available context window</td><td style="text-align:left;">Select less text or increase Context Length</td></tr><tr><td style="text-align:left;"><strong>&quot;Please adjust Max Tokens...&quot;</strong></td><td style="text-align:left;">Max Tokens is too close to Context Length</td><td style="text-align:left;">Increase Context Length on the Sampler tab</td></tr><tr><td style="text-align:left;"><strong>&quot;AI needs a larger context...&quot;</strong></td><td style="text-align:left;">System instructions consume the entire context window</td><td style="text-align:left;">Increase Context Length or decrease Max Tokens</td></tr></tbody></table><h3 id="how-truncation-works" tabindex="-1">How Truncation Works <a class="header-anchor" href="#how-truncation-works" aria-label="Permalink to &quot;How Truncation Works&quot;">​</a></h3><p>When the total input exceeds the context window:</p><ul><li><strong>In Chat (Orion)</strong>: The system prompt (Orion persona) and current question are kept. Context entries are included next. Older conversation history is dropped first.</li><li><strong>In Editor (AI Toolbar)</strong>: The selected text is kept. Context entries are dropped first if space is tight.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/ai-assistant">Use the AI assistant</a></li><li><a href="/CharacterVault/docs/configuration/sampler-settings">Adjust sampler settings</a></li><li><a href="/CharacterVault/docs/features/editor#customizing-ai-operation-prompts">Customize AI operation prompts &amp; model routing</a></li></ul>',86)])])}const u=e(s,[["render",r]]);export{c as __pageData,u as default};
